/**
 * Converts exposure time in nanoseconds to a camera shutter speed string.
 * Formats as fractional seconds (e.g., "0.5s") for exposures longer than 1 second,
 * or as fractional format (e.g., "1/30s") for standard shutter speeds.
 */
fun formatShutterSpeed(exposureTimeNs: Long): String {
    val seconds = exposureTimeNs / 1_000_000_000
    if (seconds >= 1) {

        if (seconds % 1 == 0) {
            return "${seconds}s"
        } else {

            val rounded = Math.round(seconds * 100.0) / 100.0
            return if (rounded == rounded.toInt()) {
                "${rounded.toInt()}s"
            } else {
                "${String.format("%.2f", rounded)}s"
            }
        }
    } else {


        val standardSpeeds = arrayOf(
            1000_000_000L, 500_000_000L, 250_000_000L, 125_000_000L,
            1_000_000_000L / 8, 1_000_000_000L / 15, 1_000_000_000L / 30, 1_000_000_000L / 60,
            1_000_000_000L / 125, 1_000_000_000L / 250, 1_000_000_000L / 500, 1_000_000_000L / 1000
        )
        val standardLabels = arrayOf(
            "1s", "1/2s", "1/4s", "1/8s", "1/15s", "1/30s", "1/60s", "1/125s",
            "1/250s", "1/500s", "1/1000s", "1/2000s"
        )
        var bestIndex = 0
        var bestDiff = Long.MAX_VALUE
        for (i in standardSpeeds.indices) {
            val diff = Math.abs(exposureTimeNs - standardSpeeds[i])
            if (diff < bestDiff) {
                bestDiff = diff
                bestIndex = i
            }
        }
        return standardLabels[bestIndex]
    }
}
