Move generator for a pure Python chess engine.

Handles:
- Normal piece movement
- Captures
- Pawn double pushes
- Castling ( kingside and queenside, both colors )

Does NOT handle:
- En passant
- Promotion
- Check/pin legality (though castling won't occur into check)

FEN format: rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1
Returns UCI notation: e2e4, g1f3, O-O, O-O-O, etc.
"""


def _parse_fen(fen: str):
    """Parse FEN string and return board state.

    Returns:
        board: 8x8 list of lists, each cell is piece letter (lowercase=black, uppercase=white)
        side_to_move: 'w' or 'b'
        castling: string of castle rights ('KQkq', 'Kkq', etc., may contain '-')
    """
    fields = fen.split()
    if len(fields) < 4:
        raise ValueError(f"Invalid FEN: {fen}")

    piece_placement = fields[0]
    side_to_move = fields[1]
    castling = fields[2] if len(fields) > 2 else '-'

    # Initialize empty 8x8 board
    board = [['' for _ in range(8)] for _ in range(8)]

    # Parse piece placement rank by rank (rank 8 to rank 1)
    row = 0
    col = 0
    for ch in piece_placement:
        if ch == '/':
            row += 1
            col = 0
        elif ch.isdigit():
            col += int(ch)
        else:
            board[row][col] = ch
            col += 1

    return board, side_to_move, castling


def _square_to_uci(r, c):
    """Convert internal board coordinates to UCI square.

    Board: row 0 = rank 8, row 7 = rank 1
    File: col 0 = file a, col 7 = file h
    """
    file = chr(ord('a') + c)
    rank = 8 - r
    return f"{file}{rank}"


def _uci_to_square(uci_square):
    """Convert UCI square to internal board coordinates.

    UCI: e.g. e2, a1, h8
    Returns (row, col) where row 0 = rank 8, row 7 = rank 1
    """
    file = uci_square[0]
    rank = int(uci_square[1])
    c = ord(file) - ord('a')
    r = 8 - rank
    return (r, c)


def _is_square_attacked(board, side_to_move, r, c):
    """Check if square (r, c) is attacked by the given side.

    We simulate the side to move making a move and check if the target square
