def _castling_rights_from_fen(castling):
    """Parse castling rights from FEN field.

    Returns a dict with keys: 'wk', 'wq', 'bk', 'bq' -> bool
    """
    rights = {'wk': False, 'wq': False, 'bk': False, 'bq': False}

    if castling == '-':
        return rights

    for ch in castling:
        if ch == 'K':
            rights['wk'] = True
        elif ch == 'Q':
            rights['wq'] = True
        elif ch == 'k':
            rights['bk'] = True
        elif ch == 'q':
            rights['bq'] = True

    return rights


def _castling_move_uci(castling_side, side_to_move):
    """Generate UCI for castling move.

    castling_side: 'K' (kingside white), 'Q' (queenside white),
                   'k' (kingside black), 'q' (queenside black)
    side_to_move: 'w' or 'b'
    """
    # Map castling side to UCI
    # White kingside: e1g1 -> O-O
    # White queenside: e1c1 -> O-O-O
    # Black kingside: e8g8 -> O-O
    # Black queenside: e8c8 -> O-O-O

    file_map = {'K': 'e', 'Q': 'e', 'k': 'e', 'q': 'e'}
    rank_map = {'w': '1', 'b': '8'}

    # Determine from and to squares based on side and castling type
    if side_to_move == 'w':
        rank = '1'
    else:
        rank = '8'

    if castling_side == 'K':  # White kingside
        from_sq = f"e{rank}"
        to_sq = f"g{rank}"
    elif castling_side == 'Q':  # White queenside
        from_sq = f"e{rank}"
        to_sq = f"c{rank}"
    elif castling_side == 'k':  # Black kingside
        from_sq = f"e{rank}"
        to_sq = f"g{rank}"
    elif castling_side == 'q':  # Black queenside
        from_sq = f"e{rank}"
        to_sq = f"c{rank}"
    else:
        return None

    return f"{from_sq}{to_sq}"


def _is_path_clear_for_castling(board, side_to_move, castling_side):
    """Check if the path between king and rook is clear for castling.

    For kingside: squares between e1/f1/g1 (or e8/f8/g8) must be empty
    For queenside: squares between d1/c1/b1 (or d8/c8/b8) must be empty
    """
    rank = 7 if side_to_move == 'w' else 0  # row 7 = rank 1, row 0 = rank 8

    if castling_side in ('K', 'k'):  # Kingside
        # Check files f1/f8 and g1/g8 (row, col)
        # King starts at c1/c8 (col 2), rook at a1/a8 (col 0)
        # Path: f1 (col 5) and g1 (col 6) must be empty
        # Actually king starts at e1 (col 4), rook at h1 (col 7)
        # Path squares: f1 (col 5)
        for c in range(5, 7):  # f and g files
            if board[rank][c] != '':
                return False
    elif castling_side in ('Q', 'q'):  # Queenside
        # For queenside, check squares between king and a-rook
        # King starts at e1/e8 (col 4), rook at a1/a8 (col 0)
        # Path: d1/c1/b1 (col 3,2,1) for white, or d8/c8/b8 for black
        for c in range(1, 4):  # b, c, d files (in reverse order from king)
            # Actually from king at col 4 toward a at col 0: c=3,2,1
            if board[rank][c] != '':
                return False

    return True


def _rook_starting_position(board, side_to_move, castling_side):
    """Check if the rook involved in castling is in its starting square.

    Returns the (row, col) of the rook if it can castle, or None.
    """
    rank = 7 if side_to_move == 'w' else 0

    if castling_side == 'K':  # White kingside - rook on h1
        # Rook at (7, 7) for white, (0, 7) for black
        if board[rank][7] == ('R' if side_to_move == 'w' else 'r'):
            return (rank, 7)
    elif castling_side == 'Q':  # White queenside - rook on a1
        if board[rank][0] == ('R' if side_to_move == 'w' else 'r'):
            return (rank, 0)
    elif castling_side == 'k':  # Black kingside - rook on h8
        if board[rank][7] == ('R' if side_to_move == 'w' else 'r'):
            # Actually for black, rank is 0
            if board[0][7] == 'r':
                return (0, 7)
    elif castling_side == 'q':  # Black queenside - rook on a8
        if board[rank][0] == ('R' if side_to_move == 'w' else 'r'):
            if board[0][0] == 'r':
                return (0, 0)

    return None


def _generate_castling_moves(board, side_to_move, castling):
    """Generate castling moves.

    Checks:
    - Castling right is available in FEN
    - Path between king and rook is clear
    - King does not start in check (not fully implemented - would need check detection)
    - King does not pass through or end in attacked square
    """
    moves = []
    rights = _castling_rights_from_fen(castling)
    is_white = side_to_move == 'w'

    # Kingside castling
    if rights['wk'] and is_white:
        if _is_path_clear_for_castling(board, 'w', 'K'):
            # Check king doesn't pass through attacked square
            # and doesn't end in attacked square
            # For now, just add the move - full check detection is complex
            uci = _castling_move_uci('K', 'w')
            if uci:
                moves.append(uci)

    # Queenside castling
    if rights['wq'] and is_white:
        if _is_path_clear_for_castling(board, 'w', 'Q'):
            uci = _castling_move_uci('Q', 'w')
            if uci:
                moves.append(uci)

    # Kingside castling for black
    if rights['bk'] and not is_white:
        if _is_path_clear_for_castling(board, 'b', 'k'):
            uci = _castling_move_uci('k', 'b')
            if uci:
                moves.append(uci)

    # Queenside castling for black
    if rights['bq'] and not is_white:
        if _is_path_clear_for_castling(board, 'b', 'q'):
            uci = _castling_move_uci('q', 'b')
            if uci:
                moves.append(uci)

    return moves


def _moves_for_piece(board, side_to_move, r, c):
    """Generate pseudo-legal moves for a piece at (r, c).

    We only include moves where the target square either has no piece
    or has a piece of the opposite color (captures).
    """
    piece = board[r][c]
    if piece == '':
        return []

    is_white = piece.isupper()
    # Only generate moves for the side to move
    if side_to_move == 'w' and not is_white:
        return []
    if side_to_move == 'b' and is_white:
        return []

    piece_type = piece.lower()
    moves = []

    if piece_type == 'p':
        moves = _pawn_moves(board, side_to_move, r, c)
    elif piece_type == 'n':
        moves = _knight_moves(board, side_to_move, r, c)
    elif piece_type == 'b':
        moves = _bishop_moves(board, side_to_move, r, c)
    elif piece_type == 'r':
        moves = _rook_moves(board, side_to_move, r, c)
    elif piece_type == 'q':
        moves = _queen_moves(board, side_to_move, r, c)
    elif piece_type == 'k':
        # Include castling moves for the king
        King_moves = _king_moves(board, side_to_move, r, c)
        castling = _generate_castling_moves(board, side_to_move, None)
        King_moves.extend(castling)
        moves = King_moves
    return moves


def _pawn_moves(board, side_to_move, r, c):
    """Generate pawn moves for a pawn at (r, c).

    Board: row 0 = rank 8, row 7 = rank 1.
    White pawns move decreasing row (from rank 2 toward rank 8).
    Black pawns move increasing row (from rank 7 toward rank 1).

    For this pass: single push, double push from starting rank, captures.
    """
    piece = board[r][c]
    is_white = piece.isupper()
    direction = -1 if is_white else 1

    moves = []
    row_count = len(board)  # 8

    # Single push
    target_r = r + direction
    if 0 <= target_r < row_count and board[target_r][c] == '':
        moves.append((r, c, target_r, c))

        # Double push from starting rank
        starting_row = 6 if is_white else 1
        if r == starting_row:
            target_r2 = r + 2 * direction
            if 0 <= target_r2 < row_count and board[target_r2][c] == '':
                moves.append((r, c, target_r2, c))

    # Captures (diagonal forward)
    for dc in (-1, 1):
        target_r = r + direction
        target_c = c + dc
        if 0 <= target_r < row_count and 0 <= target_c < row_count:
            target_piece = board[target_r][target_c]
            if target_piece != '':
                target_is_white = target_piece.isupper()
                # Capture only if opponent piece
                if (is_white and not target_is_white) or (not is_white and target_is_white):
