    return moves


def _knight_moves(board, side_to_move, r, c):
    """Generate knight moves (L-shifts: 2+1)."""
    piece = board[r][c]
    is_white = piece.isupper()
    row_count = len(board)

    # All 8 knight move deltas
    deltas = [(-2, -1), (-2, 1), (-1, -2), (-1, 2),
