def _bishop_moves(board, side_to_move, r, c):
    """Generate bishop moves along diagonals."""
    piece = board[r][c]
    is_white = piece.isupper()
    row_count = len(board)
    moves = []

    # Four diagonal directions
    directions = [(-1, -1), (-1, 1), (1, -1), (1, 1)]

