def _rook_moves(board, side_to_move, r, c):
    """Generate rook moves along ranks and files."""
    piece = board[r][c]
    is_white = piece.isupper()
    row_count = len(board)
    moves = []

    # Four orthogonal directions
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

