        target_c = c + dc
        if 0 <= target_r < row_count and 0 <= target_c < row_count:
            target_piece = board[target_r][target_c]
            if target_piece == '':
                moves.append((r, c, target_r, target_c))
            else:
                target_is_white = target_piece.isupper()
                if (is_white and not target_is_white) or (not is_white and target_is_white):
                    moves.append((r, c, target_r, target_c))

    return moves


def legal_moves(fen: str) -> list[str]:
    """Return every move for the side to move in UCI notation.

    UCI format: from_square_to_square, e.g. 'e2e4', 'g1f3', 'O-O', 'O-O-O'.
    """
    board, side_to_move, castling = _parse_fen(fen)

    moves = []
    for r in range(8):
        for c in range(8):
            piece_moves = _moves_for_piece(board, side_to_move, r, c)
            for (fr, fc, tr, tc) in piece_moves:
                from_uci = _square_to_uci(fr, fc)
                to_uci = _square_to_uci(tr, tc)
                moves.append(f"{from_uci}{to_uci}")

    # Add castling moves
    castling_moves = _generate_castling_moves(board, side_to_move, castling)
    moves.extend(castling_moves)

    return moves


def perft(fen: str, depth: int) -> int:
    """Return the number of leaf nodes at the given depth (perft(0) == 1).

    This is a simplified perft that counts pseudo-legal nodes.
    Handles: normal piece movement, captures, pawn double pushes,
    and castling (with path clear and rook in starting position).
    Does NOT handle: en passant, promotion, check/pin legality fully.
    """
    if depth == 0:
        return 1

    board, side_to_move, castling = _parse_fen(fen)

    # Generate all pseudo-legal moves
    all_moves = legal_moves(fen)

    if not all_moves:
        # No moves - game over (stalemate or checkmate)
        # In a real perft we'd need to distinguish, but for this pass
        # just count this as a leaf node
        return 1

    total = 0
    for move_uci in all_moves:
        # Apply the move
        # Parse UCI: from_square and to_square
        # Handle castling moves (O-O, O-O-UCI format is 2 squares, but castling
        # moves the king 2 squares, so e1g1 for O-O, e1c1 for O-O-O)
        if move_uci in ('O-O', 'O-O-O'):
            # Castling - need special handling
            # For simplicity, just count as a leaf node at this depth
            # A full implementation would apply the rook move too
            total += perft(fen, depth - 1)
